"""Curated kernel tasks live at tasks/<baseline_language>/<category>/<operator>/<scenario>/."""
from pathlib import Path

import pytest
import yaml

from src.task_contract import BASELINE_LANGUAGES, load_task_contract, validate_task_contract

ROOT = Path(__file__).resolve().parents[1]
TASKS = ROOT / "tasks"
PILOT = TASKS / "triton/normalization/rms_norm/bf16_h8192"
# Generated by agents/sikl_task_builder before review (docs/how-to/sikl-task-builder.md); not curated.
GENERATED_ROOTS = {"SIKL-task"}


def _curated_tasks() -> list[Path]:
    return sorted(path.parent for path in TASKS.rglob("task.yaml")
                  if path.relative_to(TASKS).parts[0] not in GENERATED_ROOTS)


def test_every_curated_task_is_filed_under_its_baseline_language_category_and_operator():
    tasks = _curated_tasks()
    assert tasks, "No schema-v3 tasks found"
    problems = []
    for task in tasks:
        task_id = task.relative_to(TASKS).as_posix()
        problem = load_task_contract(task / "task.yaml", task_id=task_id).layout_problem()
        if problem:
            problems.append(problem)
    assert problems == []


def test_top_level_task_directories_are_baseline_languages_or_e2e():
    top = {path.name for path in TASKS.iterdir() if path.is_dir()} - GENERATED_ROOTS
    assert top <= set(BASELINE_LANGUAGES) | {"e2e"}


@pytest.mark.parametrize("task_id", [
    "normalization/rms_norm/bf16_h8192",            # the pre-language layout
    "flydsl/normalization/rms_norm/bf16_h8192",     # wrong baseline language
    "triton/reduction/rms_norm/bf16_h8192",         # wrong category
    "triton/normalization/layer_norm/bf16_h8192",   # wrong operator
    "triton/normalization/rms_norm",                # no scenario directory
])
def test_a_misfiled_task_is_reported(task_id):
    raw = yaml.safe_load((PILOT / "task.yaml").read_text())
    workloads = yaml.safe_load((PILOT / "workloads.json").read_text())
    contract = validate_task_contract(raw, workloads, task_id=task_id)
    assert "triton/normalization/rms_norm/<scenario>" in contract.layout_problem()


def test_the_pilot_task_is_filed_correctly():
    task_id = PILOT.relative_to(TASKS).as_posix()
    assert load_task_contract(PILOT / "task.yaml", task_id=task_id).layout_problem() is None
